import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.99, D: 33.33 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withApp(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { await fn(base) } finally { server.close() }
}

async function totalFor(base, items) {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  assert.equal(res.status, 201)
  const order = await res.json()
  const fetched = await (await fetch(`${base}/orders/${order.id}`)).json()
  assert.equal(fetched.total, order.total)
  return order.total
}

// Characterization: expected values pin CURRENT behavior (total is floored to whole euros).
const cases = [
  ['single item, no discount', [{ sku: 'A', qty: 1 }], 10],
  ['multiple items, no discount', [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }], 45],
  ['fractional total is floored', [{ sku: 'B', qty: 1 }, { sku: 'C', qty: 1 }], 26],
  ['exactly 100 gets no discount', [{ sku: 'A', qty: 10 }], 100],
  ['just over 100 gets 10% off (floored)', [{ sku: 'D', qty: 4 }], 119],
  ['101 -> 90.9 floored to 90', [{ sku: 'A', qty: 10 }, { sku: 'C', qty: 1 }, { sku: 'A', qty: 0 }], 99],
  ['large order', [{ sku: 'A', qty: 100 }], 900],
  ['large mixed order', [{ sku: 'B', qty: 40 }, { sku: 'D', qty: 7 }], 1138],
]

for (const [name, items, expected] of cases) {
  test(`total: ${name}`, () => withApp(async (base) => {
    assert.equal(await totalFor(base, items), expected)
  }))
}

test('rejects empty items', () => withApp(async (base) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [] }) })
  assert.equal(res.status, 400)
}))
EOF
